/**
 * Stands in for the app's WebSocket handler module.
 *
 * The real one is generated by the build and reached through the `WS_HANDLER`
 * specifier that `src/runtime/ws-handler-bridge.js` imports; ws-handler-loader.mjs
 * points that specifier here so the gate can be tested without a build.
 *
 * LIVE BINDINGS, not an object the test mutates: `wsModule` is a module
 * namespace, which is immutable, so a test cannot assign onto it - but reading
 * `wsModule.subscribe` does follow the exported binding, which is what lets one
 * test install a hook and the next install a different one.
 */

/** @type {undefined | ((ws: any, topic: string, ctx: any) => unknown)} */
export let subscribe;

/** @type {undefined | ((ws: any, topics: string[], ctx: any) => unknown)} */
export let subscribeBatch;

/** @type {undefined | ((ws: any, topic: string, ctx: any) => unknown)} */
export let unsubscribe;

/** @type {undefined | ((ws: any, ctx: any) => unknown)} */
export let open;

/** @type {undefined | ((ws: any, ctx: any) => unknown)} */
export let message;

/** @type {undefined | ((ws: any, ctx: any) => unknown)} */
export let close;

/** @type {undefined | ((ws: any, ctx: any) => unknown)} */
export let resume;

/**
 * The handshake hook, which the upgrade path awaits. Unset by default, so
 * `typeof wsModule.upgrade === 'function'` stays false and every test that does
 * not install one takes the hookless path exactly as before.
 *
 * @type {undefined | ((req: Request, ctx: any) => unknown)}
 */
export let upgrade;

/**
 * @param {{ subscribe?: any, subscribeBatch?: any, unsubscribe?: any,
 *   open?: any, message?: any, close?: any, resume?: any, upgrade?: any }} hooks
 */
export function __setHooks(hooks) {
	subscribe = hooks.subscribe;
	subscribeBatch = hooks.subscribeBatch;
	unsubscribe = hooks.unsubscribe;
	open = hooks.open;
	message = hooks.message;
	close = hooks.close;
	resume = hooks.resume;
	upgrade = hooks.upgrade;
}
